import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 33.33, C: 0.1, D: 25 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const totalFor = async (items) => {
  const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

// These pin CURRENT behaviour (characterization), including suspect parts.
test('no discount at or below 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 5 }]), 50)
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('sums multiple line items', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'D', qty: 2 }]), 70)
})

test('10% discount applies strictly above 100', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 11 }]), 99) // 110 -> 99
  assert.equal(await totalFor([{ sku: 'D', qty: 8 }]), 180) // 200 -> 180
  assert.equal(await totalFor([{ sku: 'A', qty: 100 }]), 900) // flat rate, no tiers
})

test('discount boundary just above 100', async () => {
  // 100.1 * 0.9 = 90.09 -> floored to 90
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }, { sku: 'C', qty: 1 }]), 90)
})

test('SUSPECT: total is floored to whole euros, dropping cents', async () => {
  assert.equal(await totalFor([{ sku: 'B', qty: 1 }]), 33) // 33.33
  assert.equal(await totalFor([{ sku: 'B', qty: 4 }]), 119) // 133.32*0.9=119.988 -> 119, not 120
})

test('SUSPECT: floating point error can lose a whole unit', async () => {
  // 0.1 * 3 style drift: 3 * 0.1 = 0.30000000000000004 but 7 * 0.1 = 0.7000000000000001; pin an exact case
  assert.equal(await totalFor([{ sku: 'C', qty: 1000 }]), 100) // 100.00000000000001? no discount path check
})
EOF
